import React, { useEffect, useMemo, useRef, useState } from "react";
import { AppBar, Autocomplete, Box, Button, Chip, Stack, TextField, Toolbar, useMediaQuery, useTheme } from "@mui/material";
import { onSnapshot } from "firebase/firestore";
import { useLocation, useNavigate } from "react-router-dom";
import { brandCollectionRef, shopCollectionRef } from "../firebaseCollections";
import logo from "../logo.svg";
import { GrowerType } from "../types/grower";
import { ShopType } from "../types/shop";
import { useAuth } from "../context/AuthContext";

type SearchOption = {
    key: string;
    label: string;
    target: string;
    kind: "grower" | "shop" | "type";
};

export default function TopBar() {
    const navigate = useNavigate();
    const location = useLocation();
    const { user } = useAuth();
    const theme = useTheme();
    const isDesktop = useMediaQuery(theme.breakpoints.up("md"));
    const [visible, setVisible] = useState(true);
    const [growers, setGrowers] = useState<GrowerType[]>([]);
    const [shops, setShops] = useState<ShopType[]>([]);
    const [searchValue, setSearchValue] = useState<SearchOption | null>(null);
    const lastScrollYRef = useRef(0);

    useEffect(() => {
        const unsubscribeGrowers = onSnapshot(brandCollectionRef, (snapshot) => {
            const docs =
                snapshot.docs.some((item) => item.data()?.source === "graphql")
                    ? snapshot.docs.filter((item) => item.data()?.source === "graphql")
                    : snapshot.docs;
            setGrowers(docs.map((item) => item.data() as GrowerType));
        });

        const unsubscribeShops = onSnapshot(shopCollectionRef, (snapshot) => {
            const docs =
                snapshot.docs.some((item) => item.data()?.source === "graphql")
                    ? snapshot.docs.filter((item) => item.data()?.source === "graphql")
                    : snapshot.docs;
            setShops(docs.map((item) => item.data() as ShopType));
        });

        return () => {
            unsubscribeGrowers();
            unsubscribeShops();
        };
    }, []);

    useEffect(() => {
        const handleScroll = () => {
            const nextY = window.scrollY;
            const previousY = lastScrollYRef.current;
            const delta = nextY - previousY;

            if (delta > 8 && nextY > 90) {
                setVisible(false);
            } else if (delta < -8) {
                setVisible(true);
            }

            lastScrollYRef.current = nextY;
        };

        window.addEventListener("scroll", handleScroll, { passive: true });
        return () => window.removeEventListener("scroll", handleScroll);
    }, []);

    const options = useMemo(() => {
        const growerOptions: SearchOption[] = growers
            .filter((item) => item.shortcode && item.title)
            .map((item) => ({
                key: `g-${item.shortcode}`,
                label: item.title,
                target: `/telers/${item.shortcode}`,
                kind: "grower",
            }));

        const shopOptions: SearchOption[] = shops
            .filter((item) => item.shortcode && item.name)
            .map((item) => ({
                key: `s-${item.shortcode}`,
                label: item.name,
                target: `/cannabis-winkel/${item.shortcode}`,
                kind: "shop",
            }));

        const typeOptions: SearchOption[] = [
            { key: "type-sativa", label: "Sativa", target: "/cannabis?type=Sativa", kind: "type" },
            { key: "type-indica", label: "Indica", target: "/cannabis?type=Indica", kind: "type" },
            { key: "type-hybrid", label: "Hybrid", target: "/cannabis?type=Hybrid", kind: "type" },
        ];

        return [...typeOptions, ...growerOptions, ...shopOptions];
    }, [growers, shops]);

    useEffect(() => {
        setSearchValue(null);
    }, [location.pathname]);

    const navItems = useMemo(
        () => [
            { label: "Home", to: "/" },
            { label: "Kaart", to: "/kaart" },
            { label: "Blog", to: "/blog" },
            { label: "Cannabis", to: "/cannabis" },
            { label: "Telers", to: "/telers" },
        ],
        []
    );

    const isSelected = (target: string) => {
        if (target === "/") {
            return location.pathname === "/";
        }
        return location.pathname.startsWith(target);
    };

    return (
        <AppBar
            position="fixed"
            color="inherit"
            elevation={1}
            sx={{
                borderBottom: "1px solid #e0e0e0",
                transform: visible ? "translateY(0)" : "translateY(-110%)",
                transition: "transform 220ms ease",
                zIndex: 1200,
            }}
        >
            <Toolbar
                sx={{
                    gap: 1.5,
                    minHeight: { xs: "68px !important", md: "96px !important" },
                    px: { xs: 1, md: 2.5 },
                    maxWidth: 1130,
                    width: "100%",
                    mx: "auto",
                }}
            >
                <Box
                    component="img"
                    src={logo}
                    alt="WeedInfo"
                    sx={{ width: { xs: 44, md: 68 }, height: { xs: 44, md: 68 }, cursor: "pointer" }}
                    onClick={() => navigate("/")}
                />
                {isDesktop && (
                    <Stack direction="row" spacing={0.5} sx={{ mr: 1 }}>
                        {navItems.map((item) => (
                            <Button
                                key={item.to}
                                color={isSelected(item.to) ? "success" : "inherit"}
                                variant={isSelected(item.to) ? "contained" : "text"}
                                onClick={() => navigate(item.to)}
                                sx={{ textTransform: "none", fontWeight: 700 }}
                            >
                                {item.label}
                            </Button>
                        ))}
                    </Stack>
                )}

                <Autocomplete
                    sx={{ flex: 1, width: isDesktop ? 360 : "auto", maxWidth: "100%" }}
                    size="small"
                    options={options}
                    value={searchValue}
                    getOptionLabel={(option) => option.label}
                    isOptionEqualToValue={(option, value) => option.key === value.key}
                    onChange={(_, option) => {
                        setSearchValue(option);
                        if (option?.target) {
                            navigate(option.target);
                        }
                    }}
                    renderInput={(params) => (
                        <TextField {...params} placeholder="Zoek teler, winkel of type..." />
                    )}
                    renderOption={(props, option) => (
                        <li {...props} key={option.key}>
                            <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between", width: "100%" }}>
                                <span>{option.label}</span>
                                <Chip
                                    size="small"
                                    label={option.kind === "grower" ? "Teler" : option.kind === "shop" ? "Winkel" : "Type"}
                                />
                            </Box>
                        </li>
                    )}
                />
                {isDesktop && (
                    <Button
                        color={isSelected("/profiel") || isSelected("/login") ? "success" : "inherit"}
                        variant={isSelected("/profiel") || isSelected("/login") ? "contained" : "text"}
                        onClick={() => navigate(user ? "/profiel" : "/login")}
                        sx={{ textTransform: "none", fontWeight: 700, whiteSpace: "nowrap" }}
                    >
                        {user ? "Profiel" : "Login"}
                    </Button>
                )}
            </Toolbar>
        </AppBar>
    );
}
